/*
 * Adds the BIAT Innovation & Technology logo.
 *
 * The logo is supplied as a TRANSPARENT PNG — the white background has
 * been removed with a proper alpha channel, so it can sit on anything.
 *
 * Note on placement: BIAT's logo is dark blue (#044d80), which is
 * unreadable against the navy sidebar (#0b2545), and recolouring a bank's
 * logo would breach its brand guidelines. The sidebar header is therefore
 * a clean white band across the full width, with the logo in its own
 * colours on it.
 *
 * Save in the PROJECT ROOT and run:   node addlogo.js
 */

const fs = require('fs');
const path = require('path');

const root = __dirname;
if (!fs.existsSync(path.join(root, 'biat-frontend'))) {
  console.error('\n  ERROR: run this from the project root (the folder');
  console.error('         containing "backend" and "biat-frontend").\n');
  process.exit(1);
}

